    #[tokio::test]
    async fn open_invoice_is_found_by_order_id_until_it_closes() {
        let (db, store_id) = setup().await;
        let sid = store_id.clone();
        db.call(move |conn| insert(conn, &new_invoice(&sid, "inv_1", 1000)))
            .await
            .unwrap();

        let sid = store_id.clone();
        let hit = db
            .call(move |conn| find_open_by_order_id(conn, &sid, "wc-1234"))
            .await
            .unwrap();
        assert_eq!(hit.map(|i| i.id), Some("inv_1".to_string()));

        // Other stores and other orders never match.
        assert!(db
            .call(|conn| find_open_by_order_id(conn, "other-store", "wc-1234"))
            .await
            .unwrap()
            .is_none());

        // A cancelled invoice is not "open": a retry must mint a new one.
        let sid = store_id.clone();
        db.call(move |conn| cancel(conn, &sid, "inv_1"))
            .await
            .unwrap();
        assert!(db
            .call(move |conn| find_open_by_order_id(conn, &store_id, "wc-1234"))
            .await
            .unwrap()
            .is_none());
    }

    #[tokio::test]
    async fn payment_to_an_expired_invoice_is_recorded_as_unmatched_once() {
        let (db, store_id) = setup().await;
        let sid = store_id.clone();
        db.call(move |conn| {
            let mut inv = new_invoice(&sid, "inv_1", 1000);
            inv.expires_at = now_unix() - 1;
            insert(conn, &inv)?;
            expire_if_due(conn, "inv_1")?;
            Ok(())
        })
        .await
        .unwrap();

        let first = db
            .call(|conn| {
                record_unmatched(
                    conn,
                    &UnmatchedInput {
                        address: "ark1qinv_1",
                        rail: "ark",
                        amount_sats: 1000,
                        vtxo_id: Some("vtxo_late"),
                        txid: None,
                        detected_at: 5,
                        reason_override: None,
                    },
                )
            })
            .await
            .unwrap();
        assert!(first, "first sighting writes an audit row");
        let again = db
            .call(|conn| {
                record_unmatched(
                    conn,
                    &UnmatchedInput {
                        address: "ark1qinv_1",
                        rail: "ark",
                        amount_sats: 1000,
                        vtxo_id: Some("vtxo_late"),
                        txid: None,
                        detected_at: 5,
                        reason_override: None,
                    },
                )
            })
            .await
            .unwrap();
        assert!(!again, "re-delivery must not duplicate the row");

        // Addresses that belong to no invoice are not recorded.
        let unknown = db
            .call(|conn| {
                record_unmatched(
                    conn,
                    &UnmatchedInput {
                        address: "ark1qnobody",
                        rail: "ark",
                        amount_sats: 1,
                        vtxo_id: Some("v2"),
                        txid: None,
                        detected_at: 5,
                        reason_override: None,
                    },
                )
            })
            .await
            .unwrap();
        assert!(!unknown);
    }

    #[tokio::test]
    async fn redelivered_credited_payment_is_not_reported_as_unmatched() {
        // Regression: the watcher re-reads wallet history (barkd's
        // /wallet/history has no `since` filter, and the cursor is
        // inclusive), so a payment that already PAID an invoice is seen
        // again on later ticks. By then the invoice is no longer pending, and
        // `record_unmatched` used to log it as a "late payment".
        let (db, store_id) = setup().await;
        let sid = store_id.clone();
        db.call(move |conn| insert(conn, &new_invoice(&sid, "inv_1", 1000)))
            .await
            .unwrap();
        db.call(|conn| record_payment(conn, &obs("inv_1", "ark", 1000, Some("vtxo_1"))))
            .await
            .unwrap()
            .expect("credited");

        let reported = db
            .call(|conn| {
                record_unmatched(
                    conn,
                    &UnmatchedInput {
                        address: "ark1qinv_1",
                        rail: "ark",
                        amount_sats: 1000,
                        vtxo_id: Some("vtxo_1"),
                        txid: None,
                        detected_at: now_unix(),
                        reason_override: None,
                    },
                )
            })
            .await
            .unwrap();
        assert!(!reported, "an already-credited payment is not unmatched");
        let rows: i64 = db
            .call(|conn| {
                Ok(conn.query_row("SELECT COUNT(*) FROM unmatched_payments", [], |r| r.get(0))?)
            })
            .await
            .unwrap();
        assert_eq!(rows, 0);
    }

    #[tokio::test]
    async fn list_filters_by_status() {
        let (db, store_id) = setup().await;
        let sid = store_id.clone();
        db.call(move |conn| {
            insert(conn, &new_invoice(&sid, "inv_1", 1000))?;
            insert(conn, &new_invoice(&sid, "inv_2", 2000))?;
            cancel(conn, &sid, "inv_2")?;
            Ok(())
        })
        .await
        .unwrap();

        let pending = db
            .call(move |conn| list(conn, &store_id, Some(InvoiceStatus::Pending), None, 50))
            .await
            .unwrap();
        assert_eq!(pending.len(), 1);
        assert_eq!(pending[0].id, "inv_1");
    }
